request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-011

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "AUDITS_MULTIPLE_INVARIANTS",
    "definition": "The reasoning enumerates several independent conditions that the environment must satisfy, a single action evaluates those conditions together, and the observation reports outcomes attributable to the individual conditions.",
    "parameters": [
      {
        "name": "checklist_reasoning",
        "type": "reasoning",
        "description": "The reasoning listing the independent conditions the audit must cover."
      },
      {
        "name": "audit_action",
        "type": "action",
        "description": "The action evaluating the listed conditions together in one invocation."
      },
      {
        "name": "audit_result",
        "type": "observation",
        "description": "The observation reporting per-condition results of the audit."
      }
    ],
    "assertion_conditions": [
      "The reasoning enumerates at least two independent conditions or invariants to be verified.",
      "The audit action probes multiple of those enumerated conditions within a single invocation.",
      "The observation reports results that can be attributed to individual conditions rather than a single undifferentiated status."
    ],
    "exclusion_conditions": [
      "Only a single condition is checked.",
      "The observation aggregates outcomes so that individual conditions cannot be distinguished.",
      "The action does not actually probe the enumerated conditions."
    ]
  },
  {
    "name": "EXCLUDES_ALTERNATIVE_CANDIDATES_BY_EXHAUSTIVE_SEARCH",
    "definition": "Reasoning establishes that a candidate is unique, or that no competing candidate satisfies the relevant criterion, by directing an exhaustive search over the available artifact or corpus and interpreting the search result as excluding alternatives.",
    "parameters": [
      {
        "name": "exclusion_reasoning",
        "type": "reasoning",
        "description": "The reasoning that seeks to rule out competing candidates or confirm uniqueness."
      },
      {
        "name": "exhaustive_search_action",
        "type": "action",
        "description": "The action that enumerates occurrences of a relevant pattern or feature across the available artifact or corpus."
      },
      {
        "name": "search_result",
        "type": "observation",
        "description": "The observation listing the occurrences found by the search."
      }
    ],
    "assertion_conditions": [
      "The exclusion_reasoning identifies a need to rule out alternatives or confirm that a candidate is the only qualifying occurrence.",
      "The exhaustive_search_action searches the relevant artifact or corpus for a pattern or feature rather than checking a single known location.",
      "The search_result shows that no additional qualifying candidate was found, or that the only qualifying hit is the known candidate, and the reasoning uses this to exclude alternatives."
    ],
    "exclusion_conditions": [
      "The search is limited to a single known location and cannot reveal alternatives.",
      "The observation reports additional qualifying candidates that are not excluded.",
      "The search result is not interpreted as relevant to uniqueness or alternative exclusion.",
      "The reasoning searches for additional context about one already identified match rather than attempting to enumerate competing candidates across the artifact."
    ]
  },
  {
    "name": "VERIFIES_MULTI_INTERFACE_COMPATIBILITY",
    "definition": "The reasoning sets an acceptance requirement that an artifact must operate through multiple specified invocation interfaces or execution paths, the action exercises those paths, and the observation reports successful or equivalent outcomes from them.",
    "parameters": [
      {
        "name": "verification_reasoning",
        "type": "reasoning",
        "description": "Reasoning identifying the multiple interfaces or execution paths that must succeed."
      },
      {
        "name": "execution_action",
        "type": "action",
        "description": "Action exercising the artifact through those interfaces or paths."
      },
      {
        "name": "result_observation",
        "type": "observation",
        "description": "Observation reporting outcomes from the exercised paths."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least two specified invocation interfaces or execution paths that the artifact must satisfy.",
      "The action exercises the artifact through each of those identified paths, optionally across multiple inputs.",
      "The observation reports outcomes from those paths that can be compared for correctness or equivalence and that demonstrate successful operation."
    ],
    "exclusion_conditions": [
      "Only one invocation interface or execution path is exercised.",
      "The action only compiles the artifact or checks syntax without executing the required paths.",
      "The observation does not report outcomes for the paths being compared.",
      "At least one required path fails or produces an outcome inconsistent with the others, so compatibility is not verified.",
      "The multiple paths are not identified in the reasoning as an acceptance requirement."
    ]
  }
]

