["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA", "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE", "CONDUCTS_CONCERN_MOTIVATED_EVIDENCE_GATHERING", "IMPLEMENTS_REASONED_FAILURE_OR_RISK_RESPONSE_WITH_OBSERVED_EVIDENCE", "RECOVERS_UNUSABLE_CHECK_RESULT_VIA_METHOD_DIAGNOSIS_AND_ALTERNATIVE_RETRIEVAL", "CONFIRMS_ABSENCE_OF_UNWANTED_STATE_OR_CONTENT", "INTERPRETS_OBSERVED_STRUCTURE_OR_INFORMATIONAL_GAP_TO_DIRECT_TARGETED_ACTION", "VERIFIES_CLAIM_OR_RESULT_VIA_INDEPENDENT_COMPARISON", "RESOLVES_OBSERVED_ARTIFACT_CONFLICT_VIA_REASONED_RESOLUTION_ACTION", "RECONCILES_PRIOR_EXPECTATION_WITH_OBSERVED_OUTCOME", "VERIFIES_ACTUAL_RESULT_AGAINST_EXPECTED_CRITERIA"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "VERIFIES_MULTIPLE_TARGETS_VIA_COMPREHENSIVE_DISCRIMINATIVE_EVALUATION",
  "definition": "Reasoning identifies two or more distinct targets that must be evaluated together to establish a requirement—such as independent invariants, required invocation interfaces or execution paths, or competing candidate occurrences—directs a single comprehensive action to search, probe, or exercise all of those targets rather than a single known case, and interprets an observation that reports outcomes separately attributable to the individual targets as evidence that every required target is satisfied or covered, that the desired candidate is uniquely supported, or that alternatives are excluded.",
  "parameters": [
    {
      "name": "multi_target_requirement_reasoning",
      "type": "reasoning",
      "description": "Reasoning that identifies multiple distinct conditions, interfaces, paths, or candidate alternatives to be assessed together and that interprets the resulting outcomes as satisfying, covering, or excluding those targets."
    },
    {
      "name": "comprehensive_target_probe_action",
      "type": "action",
      "description": "A single action that comprehensively searches, probes, or exercises the multiple identified targets rather than checking only one known target."
    },
    {
      "name": "target_discriminative_observation",
      "type": "observation",
      "description": "Observation reporting outcomes that can be attributed to the individual targets, enabling comparison of success, coverage, uniqueness, or exclusion."
    }
  ],
  "assertion_conditions": [
    "The reasoning specifies at least two distinct targets to be evaluated together, such as independent invariants, required interfaces or paths, or candidate alternatives.",
    "The action performs a combined or exhaustive search, probe, or execution that covers multiple of those specified targets rather than a single known case.",
    "The observation reports outcomes attributable to the individual targets, not merely one undifferentiated status.",
    "The reasoning interprets the individually attributable outcomes as confirming that all required targets hold, that each required path or interface succeeds equivalently, or that competing alternatives are excluded."
  ],
  "exclusion_conditions": [
    "Only one target, condition, interface, path, or candidate alternative is evaluated.",
    "The action does not actually search, probe, or exercise the specified targets, for example by only compiling or checking syntax without executing required paths.",
    "The action is limited to a single known location or instance and cannot reveal or assess additional required targets or alternatives.",
    "The observation aggregates outcomes so that results cannot be attributed to individual targets.",
    "At least one required target fails or an additional unexcluded qualifying alternative remains, so the intended verification, compatibility, or uniqueness conclusion is not established.",
    "The observation is not interpreted as relevant to the multi-target requirement, coverage, compatibility, or alternative exclusion."
  ]
}

